INSERT INTO public.questions (language, level, category, question_type, question_text, options, correct_answer, explanation, image_url, audio_url, points, max_plays, order_hint, is_active) VALUES
('es','B1','listening','mcq','Escucha el audio. ¿Cuál es el objetivo principal del mensaje?','["Animar al oyente a evaluar su nivel y a unirse a la escuela","Vender material escolar","Presentar un viaje de estudios","Ofrecer un empleo de profesor"]','Animar al oyente a evaluar su nivel y a unirse a la escuela','El mensaje invita a descubrir su nivel y a unirse hoy.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,450,true),
('es','B1','listening','mcq','Escucha el audio. ¿Qué se dice sobre el nivel de los estudiantes?','["El programa sirve tanto a principiantes como a quienes quieren perfeccionarse","Solo se admite a principiantes","Hay una prueba de acceso obligatoria","Solo se acepta el nivel avanzado"]','El programa sirve tanto a principiantes como a quienes quieren perfeccionarse','El audio menciona a los estudiantes de todos los niveles.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,451,true),
('es','B1','listening','mcq','Escucha el audio. ¿Qué alcance geográfico menciona el mensaje?','["Gabón y el mundo entero","Solo Gabón","Solo España","Solo América Latina"]','Gabón y el mundo entero','Se citan las oportunidades en Gabón y en el mundo entero.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,452,true),
('es','B1','listening','mcq','Escucha el audio. La frase final «tu camino hacia el éxito empieza aquí» sugiere que...','["la escuela se presenta como el punto de partida de un recorrido","el éxito está garantizado en una semana","el curso termina muy rápidamente","el oyente ya domina el idioma"]','la escuela se presenta como el punto de partida de un recorrido','Es una fórmula de cierre que sitúa la escuela al inicio del proceso.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,453,true),
('es','B2','listening','mcq','Escucha el audio. ¿Qué registro utiliza el mensaje?','["Publicitario y motivador, dirigido directamente al oyente","Académico y neutro","Informal y humorístico","Jurídico y técnico"]','Publicitario y motivador, dirigido directamente al oyente','El tono busca convencer e implicar al oyente.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,460,true),
('es','B2','listening','mcq','Escucha el audio. La idea «no solo aprendes un idioma, construyes tu futuro» sirve para...','["asociar el aprendizaje a un beneficio personal a largo plazo","describir el precio del curso","explicar el horario de las clases","advertir de un riesgo"]','asociar el aprendizaje a un beneficio personal a largo plazo','Es un argumento de valor, no una información práctica.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,461,true),
('es','B2','listening','mcq','Escucha el audio. ¿Qué información NO aparece en el mensaje?','["El precio de la evaluación","El nombre de la escuela","El país mencionado","El tipo de seguimiento ofrecido"]','El precio de la evaluación','En ningún momento se cita una tarifa.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,462,true),
('es','B2','listening','mcq','Escucha el audio. La expresión «abrir nuevas puertas» se emplea en sentido...','["figurado, para hablar de oportunidades","literal, sobre las puertas de un edificio","irónico","técnico"]','figurado, para hablar de oportunidades','Se trata de una metáfora ligada al nombre de la escuela.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,463,true),
('es','C1','listening','mcq','Escucha el audio. ¿Con qué estrategia discursiva se abre el mensaje?','["Con una pregunta retórica dirigida al oyente","Con la cita de un experto","Con un dato estadístico","Con una anécdota personal"]','Con una pregunta retórica dirigida al oyente','El mensaje empieza interpelando al oyente con una pregunta.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,470,true),
('es','C1','listening','mcq','Escucha el audio. ¿Cómo se dirige el locutor al oyente?','["Mediante el tuteo, que crea cercanía","Mediante el usted, que marca distancia","En tercera persona","De forma impersonal"]','Mediante el tuteo, que crea cercanía','Las formas verbales están en segunda persona del singular.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,471,true),
('es','C1','listening','mcq','Escucha el audio. ¿Qué se deduce sin que se diga explícitamente?','["Que la escuela busca captar nuevos alumnos","Que la escuela es gratuita","Que la evaluación dura treinta minutos","Que la escuela tiene sedes en Europa"]','Que la escuela busca captar nuevos alumnos','Es la intención comercial implícita del mensaje.',NULL,'/__l5e/assets-v1/0f531379-cabc-473f-b520-60ab0d21446e/es-listening-opendoorsclass.mp3',1,5,472,true),
('es','A2','writing','writing','Escribe un correo electrónico (70 a 100 palabras) a un amigo para invitarlo a pasar un fin de semana en tu ciudad: propón fechas, explica qué podéis hacer juntos y pídele una respuesta.','[]','','Producción escrita evaluada sobre la realización de la tarea, la gramática, el vocabulario y la ortografía.',NULL,NULL,1,5,500,true),
('es','A2','writing','writing','Un compañero de clase estuvo enfermo la semana pasada. Escribe un mensaje (60 a 90 palabras) para contarle lo que hicisteis en clase y proponerle tu ayuda.','[]','','Producción escrita evaluada sobre la realización de la tarea, la gramática, el vocabulario y la ortografía.',NULL,NULL,1,5,501,true),
('es','A2','writing','writing','Describe (70 a 100 palabras) tu última salida o tu último viaje: adónde fuiste, con quién, qué hiciste y qué te gustó más.','[]','','Producción escrita evaluada sobre la realización de la tarea, la gramática, el vocabulario y la ortografía.',NULL,NULL,1,5,502,true),
('es','A2','speaking','speaking','Habla durante un minuto de tu ciudad o de tu barrio: cómo es, qué hay, qué te gusta y qué cambiarías.','[]','','Producción oral evaluada sobre la fluidez, la gramática, el vocabulario y la coherencia.',NULL,NULL,1,5,600,true),
('es','A2','speaking','speaking','Cuenta cómo fue tu fin de semana pasado: qué hiciste, con quién estuviste y cómo te sentiste.','[]','','Producción oral evaluada sobre la fluidez, la gramática, el vocabulario y la coherencia.',NULL,NULL,1,5,601,true),
('es','A2','speaking','speaking','Explica tus planes para los próximos meses: estudios, trabajo o proyectos personales, y por qué son importantes para ti.','[]','','Producción oral evaluada sobre la fluidez, la gramática, el vocabulario y la coherencia.',NULL,NULL,1,5,602,true);
